import java.nio.file.*;import com.example.chatbar.desktop.security.*;public class CredentialCheck {public static void main(String[] a)throws Exception {Path b=Path.of(a[0]);if(!Path.of(System.getenv("LOCALAPPDATA")).equals(b.resolve("profile/Local")))throw new Exception("ISOLATION");String v=WindowsSecretStore.Companion.create(b.resolve("environments/manual-ready/app-data")).load(new DesktopCredentialKey.ModelApiKey("unified-offline"));if(v==null||!v.startsWith("synthetic-offline-only-"))throw new Exception("NOT_SYNTHETIC");System.out.println("PROTECTED_SYNTHETIC_CREDENTIAL_OK");}}